langs = ["es","en","pt","fr","de","it"]
lines = ["    legalI18n: {"]
for l in langs:
    lines.append("        %s: {" % l)
    for key, vals in T.items():
        v = vals[langs.index(l)]
        esc = v.replace("\\","\\\\").replace("'","\\'")
        lines.append("            '%s': '%s'," % (key, esc))
    lines.append("        },")
lines.append("    },")
block = "\n".join(lines) + "\n"

s = io.open(P, encoding="utf-8", newline="").read()
marker = "    init() {\n        for (const lang in this.homeI18n) {"
assert marker in s
s = s.replace(marker, block + "\n" + marker, 1)
old_loop = """        for (const lang in this.extraI18n) {
            this.translations[lang] = Object.assign({}, this.translations[lang], this.extraI18n[lang]);
        }"""
new_loop = old_loop + """
        for (const lang in this.legalI18n) {
            this.translations[lang] = Object.assign({}, this.translations[lang], this.legalI18n[lang]);
        }"""
assert old_loop in s
s = s.replace(old_loop, new_loop, 1)
io.open(P, "w", encoding="utf-8", newline="\n").write(s)
print("legalI18n keys:", len(T))
